function Counter({
  target,
  suffix,
  decimals,
  active,
}: {
  target: number;
  suffix: string;
  decimals: number;
  active: boolean;
}) {
  const [display, setDisplay] = useState(decimals > 0 ? "0.00" : "0");
  const obj = useRef({ val: 0 });

  useEffect(() => {
    if (!active) return;
    obj.current.val = 0;
    gsap.to(obj.current, {
      val: target,
      duration: 2,
      ease: "power2.out",
