        setDisplay(
          decimals > 0
            ? obj.current.val.toFixed(decimals)
            : String(Math.round(obj.current.val))
        );
      },
    });
  }, [active, target, decimals]);

  return (
    <span>
      {active ? display : decimals > 0 ? target.toFixed(decimals) : target}
